from fastapi import APIRouter
import pandas as pd

router = APIRouter()

@router.get("/forecast/ensemble/{symbol}")
def ensemble_forecast(symbol: str):
    """
    Returns ensemble predictions for a stock.
    """
    # Load CSV generated by forecasting ensemble
    df = pd.read_csv("app/services/ensemble_predictions.csv")

    # For simplicity, return last 100 predictions
    last_100 = df.tail(100)

    return {
        "symbol": symbol,
        "Actual": last_100["Actual"].tolist(),
        "XGB": last_100["XGB"].tolist(),
        "LSTM": last_100["LSTM"].tolist(),
        "Ensemble": last_100["Ensemble"].tolist()
    }
